#include <stdio.h>



int main(void)
{
    int a[4] = {10, 30, 40};
    int n = 3;
    for (int i = n; i > 1; i--) {
        a[i] = a[i - 1];
    }
    a[1] = 20;
    n++;
    for (int i = 0; i < n; i++) {
        printf("%s%d", i == 0 ? "" : " ", a[i]);
    }
    putchar('\n');
    return 0;
}

#include <stdio.h>



int main(void)
{
    int a[] = {3, 6, 9};
    int n = 3;
    for (int i = 0; i < n - 1; i++) {
        a[i] = a[i + 1];
    }
    n--;
    printf("%d %d\n", a[0], a[n - 1]);
    return 0;
}

