    for (int i = n; i > 1; i--) {
        a[i] = a[i - 1];
    }
    a[1] = 20;
    n++;
    for (int i = 0; i < n; i++) {
        printf("%s%d", i == 0 ? "" : " ", a[i]);
    }
    putchar('\n');
    return 0;
}
